-- ----------------------------
-- View structure for `view_bidding`
-- ----------------------------
DROP VIEW IF EXISTS `view_bidding`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `view_bidding` AS select `bidding`.`BusinessID` AS `BusinessID`,`bidding`.`BusinessTitle` AS `BusinessTitle`,`bidding`.`ProjectID` AS `ProjectID`,`bidding`.`ReleaseCom` AS `ReleaseCom`,`bidding`.`Money` AS `Money`,`bidding`.`Supplier` AS `Supplier`,`bidding`.`ReleaseTime` AS `ReleaseTime`,`bidding`.`DetileURL` AS `DetileURL`,`bidddetile`.`Content` AS `Content`,`bidding`.`Source` AS `Source`,`bidding`.`UpdateTime` AS `UpdateTime` from (`bidding` join `bidddetile`) where ((`bidding`.`BusinessID` = `bidddetile`.`BusinessID`) and (`bidding`.`ReleaseTime` > (curdate() + interval -(450) day))) order by `bidding`.`ReleaseTime` desc ;

-- ----------------------------
-- View structure for `view_querykeyword`
-- ----------------------------
DROP VIEW IF EXISTS `view_querykeyword`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `view_querykeyword` AS select `business`.`BusinessID` AS `BusinessID`,`business`.`BusinessTitle` AS `BusinessTitle`,`detile`.`Content` AS `Content` from (`business` join `detile`) where ((`business`.`BusinessID` = `detile`.`BusinessID`) and (`business`.`ReleaseTime` > (curdate() + interval -(400) day))) ;
